import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { TextField, Button, Box, Typography, Link, AppBar, Toolbar } from '@mui/material';
import { motion } from 'framer-motion';

const pageVariants = {
  initial: { opacity: 0, y: 50 },
  animate: { opacity: 1, y: 0 },
  exit: { opacity: 0, y: -50 },
};

function LandingPage() {
  const [formData, setFormData] = useState({ email: '', password: '' });
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleLogin = () => {
    // Add login logic here
    console.log('Customer Login:', formData);
  };

  return (
    <motion.div
      variants={pageVariants}
      initial="initial"
      animate="animate"
      exit="exit"
      transition={{ duration: 0.5 }}
    >
      {/* Header */}
      <AppBar position="static" sx={{ backgroundColor: '#1e1e1e', padding: 1 }}>
        <Toolbar>
          <Typography
            variant="h6"
            sx={{
              flexGrow: 1,
              display: 'flex',
              alignItems: 'center',
              fontFamily: 'Space Grotesk',
            }}
          >
            SpinSmart
            <img
              src="/assets/laundry-machine.png" // Ensure this path matches your logo location
              alt="Laundry Machine Logo"
              style={{ marginLeft: 10, height: 40 }}
            />
          </Typography>
        </Toolbar>
      </AppBar>

      {/* Login Form */}
      <Box
        sx={{
          height: 'calc(100vh - 64px)', // Adjust height to exclude AppBar
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          backgroundColor: '#121212',
          color: '#ffffff',
          padding: 2,
          fontFamily: 'Space Grotesk',
        }}
      >
        <Box
          sx={{
            width: '100%',
            maxWidth: 400,
            backgroundColor: '#1e1e1e',
            padding: 4,
            borderRadius: 2,
            boxShadow: '0 4px 10px rgba(0, 0, 0, 0.3)',
          }}
        >
          <Typography
            variant="h5"
            gutterBottom
            align="center"
            sx={{ fontFamily: 'Space Grotesk' }}
          >
            Customer Login
          </Typography>
          <TextField
            label="Email"
            name="email"
            type="email"
            variant="outlined"
            fullWidth
            margin="normal"
            value={formData.email}
            onChange={handleChange}
            required
            InputLabelProps={{ style: { color: '#b0bec5', fontFamily: 'Space Grotesk' } }}
            InputProps={{
              style: { color: '#ffffff', fontFamily: 'Space Grotesk' },
            }}
          />
          <TextField
            label="Password"
            name="password"
            type="password"
            variant="outlined"
            fullWidth
            margin="normal"
            value={formData.password}
            onChange={handleChange}
            required
            InputLabelProps={{ style: { color: '#b0bec5', fontFamily: 'Space Grotesk' } }}
            InputProps={{
              style: { color: '#ffffff', fontFamily: 'Space Grotesk' },
            }}
          />
          {error && (
            <Typography
              color="error"
              variant="body2"
              sx={{ marginTop: 1, fontFamily: 'Space Grotesk' }}
            >
              {error}
            </Typography>
          )}
          <Button
            variant="contained"
            color="primary"
            fullWidth
            sx={{ marginTop: 2, fontFamily: 'Space Grotesk' }}
            onClick={handleLogin}
          >
            Login
          </Button>
        </Box>

        {/* Admin Login Link */}
        <Typography
          variant="body2"
          sx={{
            marginTop: 2,
            cursor: 'pointer',
            textDecoration: 'underline',
            fontFamily: 'Space Grotesk',
          }}
          onClick={() => navigate('/admin-login')}
        >
          Admin Login
        </Typography>
      </Box>
    </motion.div>
  );
}

export default LandingPage;
